return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ha','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T16:59:17+00:00','po-revision-date'=>'2026-09-26T16:59:17+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Fitowar farko ta sabon Page Builder Sandwich da aka sake ginawa: saituna da allon Game da Mu, yadidin fitarwa na gaba mai tsabta ba tare da alamar SEO ba, da kuma tubalin abun ciki guda daya.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Masu ba da sabis na AI','The makers of ChatGPT. A good all-rounder.'=>'Masu aikata ChatGPT. Kwararren mai yin komai sosai.','The makers of Claude. Strong at writing and careful reasoning.'=>'Masu ƙirƙirar Claude. Suna da ƙarfi wajen rubutawa kuma suna da hankali wajen yin la\'akari.','Google\'s Gemini models. Fast and inexpensive.'=>'Samfurin Gemini na Google. Masu sauri da rahusa.','A European AI company with fast, inexpensive models.'=>'Wani kamfanin AI na Turai mai sauri da arha samfura.','Low-cost models that are good at writing and code.'=>'Samfuran mai sauƙi waɗanda ke da kyau wajen rubutu da lissafi.','One key for models from many different providers.'=>'Maɓalli guda ɗaya don samfuran daga masu samarwa daban-daban.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Duk wani sabis da ke aiki kamar API na OpenAI, gami da samfurin da ke aiki akan kwamfutarka ko uwar garken ka.','General (used when nothing more specific is set)'=>'Gabaɗaya (ana amfani da shi lokacin da babu takamaiman abin da aka saita)','Writing and rewriting'=>'Rubuta da sake rubutawa','Translation'=>'Fassara','Code and CSS'=>'Lamba da CSS','Sorry, you are not allowed to access this page.'=>'Yi hakuri, ba a ba ka izinin shiga wannan shafin ba.','These settings are shared by every plugin that uses them: %s.'=>'Wadannan saitunan suna da alaƙa da kowane plugin da ke amfani da su: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'An ɓoye Maɓallanka a cikin bayanan wannan shafin kuma ana aika su ne kawai zuwa ga mai ba da sabis da kuka zaɓa - ba za a taba aika su gare mu ba.','Step 1 of 2: choose an AI provider'=>'Mataki na 1 na 2: zabi mai ba da sabis na AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Kuna kawo naku key, don haka kuna biyan mai ba da sabis ɗin kai tsaye don abin da kuka yi amfani da shi. Ba ku da tabbas? Ko wanne daga cikin waɗannan yana aiki sosai; za ku iya ƙara ƙarin daga baya.','Next'=>'Na gaba','Step 2 of 2: connect %s'=>'Mataki na 2 na 2: haɗa %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Shigar da adireshin sabis ɗin da ke da jituwa da OpenAI, wanda ya ƙare da /v1. Ana buƙatar maɓalli ne kawai idan sabis ɗin ya nemi ɗaya.','Open %s and sign in (or create a free account).'=>'Buɗe %s sannan ka shiga (ko ka ƙirƙiri sabon ajiya kyauta).','the %s API keys page'=>'shafin mabulsan API na %s','Create a new key and copy it.'=>'Ƙirƙiri sabuwar maɓalli sannan ka kwafi ita.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Li manna shi a kasa sannan a danna "Ajiye a gwada". Muna tura karamin buƙatu guda ɗaya don bincika yana aiki.','Most providers need a little credit on the account before a key works: %s.'=>'Yawancin masu ba da sabis suna buƙatar ɗan kuɗi a cikin asusun kafin maɓalli ya yi aiki: %s.','add credit'=>'ƙara bashi','← Choose a different provider'=>'← Zabi wani mai ba da sabis daban','Address'=>'Adireshin','Saved key ends in …%s — paste a new one to replace it'=>'Aɓuƙan da aka ajiye yana ƙarewa a …%s — liƙa sabo don maye gurbin sa','Key (optional)'=>'Maɓalli (zaɓi)','API key'=>'Maɓallin API','Save and test'=>'Ajiye kuma a gwada','Providers'=>'Masu bada sabis','Provider'=>'Mai ba da sabis','Status'=>'Matsayi','Key'=>'Maɓalli','Get a key'=>'Samu maɓalli','Test'=>'Gwaji','Remove'=>'Cire','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Wanda wani sabon sigar plugin ya adana: sabunta wannan plugin ɗin, ko kuma a sake shigar da mabudin.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Ba za a iya buɗe maɓallin da aka ajiye ba kuma (an canza maɓallin tsaro na shafin). Shigar da shi sake.','Not connected'=>'Ba a haɗa ba','Connected — last test passed %s'=>'An haɗa — gwajin ƙarshe ya yi nasara %s','Last test failed: %s'=>'Gwajin da ya gabata ya gaza: %s','Connected — not tested yet'=>'An haɗa — ba a gwada ba tukuna','Which model to use'=>'Wane model za a yi amfani da shi','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ yana nuna shawararmu don wannan aikin. Jerin ya ƙunshi kowane samfurin da maɓallinku zai iya amfani da shi, wanda aka karanta kai tsaye daga mai bada sabis ɗin.','— Recommended for the provider —'=>'— An ba da shawarar ga mai bada sabis —','Save models'=>'Ajiye samfura','Refresh the model lists from the providers'=>'Sabunta jerin samfuran daga masu samarwa','best quality'=>'mafi kyau','lowest cost'=>'mafi ƙarancin farashi','fastest'=>'mafi sauri','Add a model yourself'=>'Ƙara samfuri da kanka','A model came out today? Paste its exact name to use it straight away.'=>'An fitar da sabon samfuri a yau? Manna daidai sunansa don amfani da shi nan take.','Model name'=>'Sunan samfurin','Add model'=>'Ƙara samfurin','Recommended models list'=>'Jerin samfuran da aka ba da shawarar','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Ba a iya tabbatar da jerin samfuran da aka ba da shawarar ba, don haka ba a nuna shawarwari ba. Sake shigar da plugin ɗin, ko kuma kunna sabuntawa na yau da kullum a ƙasa.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Jerin da ake amfani da shi an wallafa shi ne a ranar %s. Kowane sabuntawar kari (plugin) yana kawo sabon guda ɗaya.','Also check Zinn Digital® once a day for an updated list.'=>'Hakanan a bincika Zinn Digital® sau ɗaya a rana don samun sabon jerin sunaye.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Ana aika da sauƙaƙe buƙatar saukarwa kawai: babu makulli, babu adireshin shafin, babu wani abu game da abun ciki naka. An sanya hannu kan jerin, kuma an yi watsi da jerin da ya kasa binciken sa hannu.','Last checked %1$s: %2$s.'=>'An bincika karshe a %1$s: %2$s.','Save, and check now if turned on'=>'Ajiye, sannan a duba yanzu idan an kunna','a newer list was installed'=>'an shigar da sabon jerin sunaye','already up to date'=>'rigakafi da sabuntawa','the download failed the signature check and was ignored'=>'zazzakunan sun gaza wuce gwajin sa hannu kuma an yi watsi da su','Zinn Digital® could not be reached; the current list stays in use'=>'Ba za a iya isa ga Zinn Digital® ba; jerin na yanzu zai ci gaba da amfani','turned off'=>'an kashe','Open'=>'Buɗe','Check their status page'=>'Bincika shafin yanayin su','Open your billing page'=>'Buɗe shafin kuɗi naka','Open your API keys page'=>'Buɗe shafin maɓallan API naka','Open the AI settings'=>'Buɗe saitunan AI','Sorry, you are not allowed to do that.'=>'Yi hakuri, ba a ba ka izinin yin hakan ba.','Unknown provider.'=>'Ba a san mai ba da sabis ba.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Shigar da adireshin sabis ɗinku, alal misali http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Wannan ba ya yi kama da maɓallin API ba. Sake kwafin sa, ba tare da guraben sarari ba.','Paste your API key first.'=>'Da farko a liƙa maɓallin API ɗinka.','Key removed.'=>'An cire maɓallin.','Models saved.'=>'An adana samfuran.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Shigar dainiyar sunan samfurin, misali yadda takardun bayanin mai ba da sabis suka rubuta shi.','Added %s. Choose it under "Which model to use".'=>'An ƙara %s. Zaɓi shi a ƙarƙashin "Wane samfuri za a yi amfani da shi".','Model removed.'=>'An cire samfurin.','Daily updates are off. The list that came with the plugin is used.'=>'An kashe sabuntawa kullum. Ana amfani da jerin da ya zo tare da plugin din.','Checked: %s.'=>'An Duba: %s.','Model lists refreshed.'=>'An sabunta jerin samfuran.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Wani sabon sigar na ɗaya daga cikin plugins ɗinka ya adana maɓallin AI ɗinka. Sabunta wannan plugin ɗin, ko kuma ka sake shigar da maɓallin a cikin saitunan AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Ba za a iya buɗe maɓallin AI ɗinka da aka ajiyage ba (maɓallan tsaron rukunin yanar gizon sun canza). Sake shigar da shi a cikin saitunan AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Ba a saita AI ba tukuna. Ƙara maɓalli don mai ba da AI a cikin saitunan AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Ba a zaɓi samfurin ba don wannan aikin. Zaɓi ɗaya a cikin saitunan AI.','That AI provider is not supported by this version of the plugin.'=>'Wannan mai ba da sabis na AI ba a goyi bayansa da wannan sigar ta plugin ba.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Wannan shafin bai iya tuntuɓar sabis ɗin AI naka ba. Bincika cewa yana aiki kuma ana iya isa ga adireshinsa daga sabar gidan yanar gizon ku (sabis da ke kan kwamfutarka ba zai iya isa ba daga shafin da aka karɓa).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Wannan shafin bai iya isa ga %s ba. Duba shafin matsayinsu; idan suna aiki, mai masaukin ku na iya toshe haɗin da ke fita, ko kuma adireshin ba daidai bane.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s ya ce asusunka ba shi da kuɗi ko kuma adadin da ya rage. Ƙara kuɗi ko ɗaga iyakar a cikin asusunka tare da su, sannan a sake gwadawa.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s bai karɓi makullin ku ba. Wataƙila an rubuta shi ba daidai ba, an soke shi ko kuma ya ƙare. Ƙirƙiri sabon maɓalli sannan ka manna shi a nan.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ya ki amincewa da wannan buƙatar don maɓallinka. Wataƙila maɓallin ba shi da damar shiga wannan samfurin ko fasalin, ko kuma asusunka yana buƙatar tabbatarwa.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Samfurin "%1$s" ba ya samuwa daga %2$s don maɓallin ku. Zaɓi wani samfuri a cikin saitunan AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Tsarin ku na %2$s bai haɗa da samfurin "%1$s" ba. Zaɓi wani samfurin a cikin saitunan AI, ko haɓaka tsarin ku tare da su.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s tana iyakance saurin da makullin ku ke iya aika buƙatu. Jira minti ɗaya kuma sake gwadawa, ko ku ɗaga iyakacin ƙimar ku tare da su.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s yana fuskantar matsaloli a halin yanzu (akwai katsewa ko kuma cunkoso a gefensu). Babu wani abu da ba daidai ba tare da saitunanka. Gwada sake nan ba da dadewa ba.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Om karakteristik AI ta gaza saboda dalilin da ba za mu iya gane shi ba. Sake gwadawa; idan hakan ta ci gaba da faruwa, tuntuɓi sashen goyon baya tare da cikakkun bayanan da ke ƙasa.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Mai ba da sabis na AI ya ba da amsa a wata sifa da wannan plugin ɗin bai iya karantawa ba. Sake gwadawa; idan hakan ya ci gaba da faruwa, zaɓi wani samfurin ko tuntuɓi goyon baya.','Custom (OpenAI-compatible)'=>'Keɓaɓɓe (Mai jituwa da OpenAI)','Save a key for this provider first.'=>'Farko a adana maɓalli don wannan mai ba da sabis.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Maɓallin ku yana aiki, amma mai ba da sabis ɗin bai lissafa wani samfurin rubutu don shi ba. Ƙara wani samfurin da kanka a ƙasa.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'An haɗa. %1$s ya/ta amsa ta amfani da %2$s. Siffofin AI ɗinka suna shirye don amfani.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Ba a ba matsayin mai amfani da ku izinin amfani da AI a wannan rukunin yanar gizon ba. Tambayi mai gudanarwa.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Wannan shafin ya kai iyakar kasafin kuɗinsa na AI na wata-wata. Mai gudanarwa zai iya ƙara shi a cikin saitunan AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Wannan shafin ya kai iyakar buƙatunsa na AI na wata-wata. Mai gudanarwa zai iya ƙara ta a cikin saitunan AI.','Usage and cost'=>'Amfani da kuma tsada','The log, limits and role permissions apply to AI used through: %s.'=>'Rubutun shiga, iyakoki da izinin matsayi suna aiki kan AI da ake amfani da ita ta: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Kudin sun kusa zama daidai, an lissafa su ne daga farashin da aka buga; samfurin da babu wani sanannen farashi yana da darajar sifili.','This month: %1$s requests, about %2$s.'=>'Wannan wata: buƙatun %1$s, kimanin %2$s.','When'=>'Lokacin da','Who'=>'Waye','Used for'=>'A yi amfani da shi don','Model'=>'Samfurin','Tokens in / out'=>'Alamar shiga / fita','About'=>'Game da Mu','Result'=>'Sakamako','No AI requests have been made yet.'=>'Ba a yi roƙon AI ko ɗaya ba tuƙuna.','Done'=>'An gama','Limits and permissions'=>'Iyakoki da izini','Monthly spending limit (US dollars)'=>'Iyakar kashe kuɗi ta wata-wata (US dollars)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Bar shi babu komai don babu iyaka. AI zai tsaya na sauran watan da zarar kudin da aka kiyasta sun kai wurin.','Monthly request limit'=>'Iyakokin buƙatu na kowane wata','Leave empty for no limit.'=>'Bar shi a ba komai don babu iyaka.','Who may use AI'=>'Wane ne zai iya amfani da AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Cirewa ba tare da zabi ba don barin kowa wanda zai iya amfani da fasalullukan plugin ɗin ya yi amfani da AI. Masu gudanarwa za su iya amfani da shi kowane lokaci.','Save limits and permissions'=>'Ajiye iyakoki da izini','Limits and permissions saved.'=>'An adadin da izini an adana.','Security error, please refresh the page and try again.'=>'Kuskuren tsaro, don Allah sake loda shafin kuma a sake gwadawa.','Missing newsletter settings. Please contact the admin.'=>'Saitunan wasiƙar labarai sun ɓace. Da fatan za a tuntuɓi mai gudanarwa.','Invalid newsletter settings. Please contact the admin.'=>'Saitunan jaridar labarai ba su da inganci. Da fatan za a tuntuɓi mai kula da tsarin.','Invalid email address.'=>'Anwani ta imel ba daidai ba ce.','Too many attempts. Please try again in a few minutes.'=>'Kokarin da yawa. Da fatan za a sake gwadawa bayan \'yan mintoci kaɗan.','Something went wrong. Please contact the admin.'=>'Wani abu ya lalace. Da fatan za a tuntuɓi mai gudanarwa.','Map'=>'Taswira','Background video'=>'Bidiyon bango','%1$s: %2$d font files stored, stylesheet %3$s'=>'%1$s: Fayilolin rubutu %2$d da aka adana, takardar salo %3$s','That family is not stored.'=>'Ba a adana wannan iyalin ba.','Removed.'=>'An cire.','That is not a valid font family name.'=>'Wannan ba ingantaccen sunan iyalin rubutu ba ne.','Google Fonts did not return that family. Check the name and try again.'=>'Google Fonts bai dawo da wannan iyalin ba. Duba sunan sannan a sake gwadawa.','The font files could not be downloaded or saved. Check that the uploads folder is writable.'=>'Ba a iya sauke ko adana fayilolin rubutun ba. Tabbatar cewa foldar loda tana da ikon rubutawa.','The font stylesheet could not be saved. Check that the uploads folder is writable.'=>'Ba a iya adana takardar salon haruffa (font stylesheet) ba. Duba ko babban fayil din loda abubuwa (uploads folder) yana da ikon karɓar rubutu.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Babu rubutun allo na mai gudanarwa a cikin wannan kwafin na plugin ɗin. Sake shigar da shi daga fakitin da aka fitar.','This screen needs JavaScript.'=>'Wannan allon yana buƙatar JavaScript.','Languages'=>'Harsuna','Upgrade'=>'Haɓaka','Pricing'=>'Farashin kaya','Start Trial'=>'Fara Gwaji','Account'=>'Asusun ajiya','Contact Us'=>'Tuntuɓe Mu','Affiliation'=>'Hadin gwiwa','the kind of softwarePlugin'=>'Fifikal','greetingHey %s,'=>'Sannu %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Yi rijista don karɓar sanarwar imel don sabunta tsaro da abubuwa, abubuwan ilimi, da lokaci-lokaci, da kuma raba wasu mahimman bayanan muhalli na WordPress. Wannan zai taimaka mana mu sanya %s ya fi dacewa da rukunin yanar gizon ku kuma ya fi kyau wajen yin abin da kuke buƙatar ya yi.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Zabi ka karɓi sanarwar imel don sabunta tsaro & fasali, abubuwan ilimi, da lokaci-lokaci, da kuma raba wasu basic WordPress environment info.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Idan ka tsallake wannan, babu damuwa! %1$s zai ci gaba da aiki sosai.','Allow & Continue'=>'Bada dama & Ci gaba','verbSkip'=>'Tsallake','Skipping, please wait'=>'Ana tsallakewa, don Allah a jira','Continue'=>'Ci gaba','Please wait'=>'Don Allah jira','as activating pluginActivating'=>'Ana kunnawa','This will allow %s to'=>'Wannan zai ba %s damar','Privacy Policy'=>'Manufar Keɓantawa','Terms of Service'=>'Sharuɗɗan Sabis','License Agreement'=>'Yarjejeniyar Lasisi','Have a license key?'=>'Kuna da maɓallin lasisi?','Activate License'=>'Kunna Lasisi','View Basic Profile Info'=>'Duba Ingantaccen Bayanin Bayanin Asali','Your WordPress user\'s: first & last name, and email address'=>'Mai amfani da WordPress naka: suna da sunan mahaifi, da adireshin imel','View Basic Website Info'=>'Duba Cikakken Bayanin Yanar Gizo na Asali','Homepage URL & title, WP & PHP versions, and site language'=>'URL da taken shafi na gida, sifofin WP da PHP, da harshen shafin','View Basic %s Info'=>'Duba Babban Bayanin %s','Current %s & SDK versions, and if active or uninstalled'=>'Sigogin %s & SDK na yanzu, da ko suna aiki ko an cire su','Newsletter'=>'Wasiƙar labarai','Updates, announcements, marketing, no spam'=>'Sabuntawa, sanarwa, tallace-tallace, babu zamba','View Diagnostic Info'=>'Dubi Bayanan Bincike','WordPress & PHP versions, site language & title'=>'Sigarorin WordPress & PHP, harshen shafin & take','View Plugins & Themes List'=>'Duba Lissafin Na\'urorin Haɗi da Jigo','Names, slugs, versions, and if active or not'=>'Sunaye, alamomi, juzu\'i, da ko a kunna ko a\'a','optional'=>'na zaɓi ba','Never miss an important update'=>'Kada ka taba rasa muhimman sabuntawa','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Mun gabatar da wannan zaɓi don kar ka taɓa rasa wani muhimmin sabuntawa kuma ka taimake mu mu sanya %s ya fi dacewa da shafin yanar gizon ku kuma ya fi kyau wajen yin abin da kuke buƙatar ya yi.','Thank you for updating to %1$s v%2$s!'=>'Na gode da sabuntawa zuwa %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Dole ne prefix ya zama haruffa ƙanana 1 zuwa 8 ko lambobi, ya kafa da harshe, kuma kada ya sanya wa plugin suna.','You are not allowed to edit this item.'=>'Ba a ba ku izinin gyara wannan abu ba.','You are not allowed to do this.'=>'Ba a ba ka izinin yin wannan ba.','Safe mode was turned off because it no longer matches your login. Reload the page.'=>'An kashe yanayin tsaro domin baya dace da shigarka ta gaba. Sake loda shafin.','Only an administrator can use safe mode.'=>'Mai gudanarwa ne kawai zai iya amfani da yanayin aminci.','Safe mode needs a normal browser login.'=>'Yanayin aminci yana buƙatar shiga ta na\'urar bincike ta al\'ada.','Safe mode could not be set up.'=>'Ba a iya saita yanayin aminci ba.','Safe mode needs write access to the wp-content/mu-plugins folder.'=>'Yanayin tsaro yana buƙatar damar rubutawa zuwa ga babban fayil na wp-content/mu-plugins.','Safe mode could not write to the wp-content/mu-plugins folder.'=>'Ba a iya rubuta wa zuwa cikin kundin adireshi na wp-content/mu-plugins ba a yanayin kariya (Safe mode).','Sandwich Studio'=>'Sandwich Studio','That page does not exist, or it has been deleted.'=>'Wannan shafin babu shi, ko kuma an goge shi.','Sorry, you are not allowed to edit this item in Sandwich Studio.'=>'Yi hakuri, ba a ba ka izinin gyara wannan abu a cikin Sandwich Studio ba.','Sandwich Studio is not built. Reinstall the plugin.'=>'Ba a gina Sandwich Studio ba. Sake shigar da plugin ɗin.','Add title'=>'Ƙara take','Type / to choose a block'=>'Rubuta / don zaɓar wani b da ke rufe','Loading Sandwich Studio…'=>'Ana loda Sandwich Studio...','Sandwich Studio needs JavaScript. Use the normal editor instead.'=>'Sandwich Studio na buƙatar JavaScript. Yi amfani da madadin edita na al\'ada maimakon haka.','Edit “%s” with Sandwich Studio'=>'Gyara “%s” tare da Sandwich Studio','Edit with Sandwich Studio'=>'Gyara tare da Sandwich Studio','Blank canvas'=>'Fanko mara komai','A migration step is running right now. Try again in a minute.'=>'Ana gudanar da wani matakin kaura a yanzu. Sake gwadawa bayan minti daya.','Thank you for subscribing!'=>'Na gode da yin rajista!','Something went wrong. Please contact the administrator.'=>'Wani abu ya tafi ba daidai ba. Da fatan za a tuntuɓi mai kula da tsarin.','Years'=>'Shekaru','Months'=>'Watanni','Weeks'=>'Makonni','Days'=>'Kwanaki','Hours'=>'Awanni','Minutes'=>'Minti','Seconds'=>'Dakiku','Go to slide %d'=>'Je zuwa zamewa ta %d','You\'re already subscribed to our newsletter'=>'Kun riga kun yi rajista ga jaridarmu','Email address is already subscribed.'=>'An riga an yi rijistar adireshin imel din.','MailPoet plugin not found. Please contact the admin.'=>'Ba a sami plugin din MailPoet ba. Da fatan za a tuntuɓi mai kula da tsarin.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Wanda Neil Lock, Babban Jami\'in Gudanarwa na Zinn Digital® Ltd ya gina','Version %s'=>'Sigar %s','Page Builder Sandwich website'=>'Shafin Yanar Gizo na Page Builder Sandwich','Zinn Digital® website'=>'Shafin yanar gizo na Zinn Digital®','Settings saved.'=>'An adana saitunan.','See the Pro plans and pricing'=>'Duba shirin Pro da farashinsa','Front-end output'=>'Fitowar gaban shafin','Class name prefix'=>'Ratabayon sunan Class','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Kowane sunan aji da filogin ke bugawa akan shafukanku yana farawa da wannan gaba, ta yadda shafukan ba za su bayyana wane filogin ne ya gina su ba. Haruffa kanana ko lambobi 1 zuwa 8, wadanda suka fara da harafi.','Save'=>'Ajiye','Beta updates'=>'Sabuntawar Beta','This site receives beta versions as updates.'=>'Wannan shafin yana karɓar nau\'ikan beta azaman sabuntawa.','This site receives stable versions only.'=>'Wannan shafin yana karɓar ingantattun sassa kawai.','Change this on the Account page'=>'Canza wannan a shafin Asusu','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Ana bayar da nau\'ikan Beta ga shigarwar Pro da ke da lasisi waɗanda ke haɗa da asusun su. Da zarar an haɗa, zaku iya shiga daga shafin Asusun.','The request converting this post stopped before it finished, so the post was skipped. Open it to convert it, or convert it again from here.'=>'An dakatar da juya wannan post din kafin a gama, don haka an tsallake post din. Buɗe shi don juya shi, ko kuma ka sake juya shi daga nan.','There is no backup of this post to restore.'=>'Babu wani ajiyar baya na wannan wallafe-wallafen da za a dawo da shi.','The converted content could not be saved.'=>'Ba a iya adana abin da aka canza ba.','Unknown error.'=>'Kuskure wanda ba a sani ba.','No legacy content has been checked yet.'=>'Ba a bincika wani tsohon abun ciki ba tukuna.','Restoring legacy content: %1$d of %2$d posts.'=>'Maido da tsohon abun ciki: %1$d na %2$d posts.','Converting legacy content: %1$d of %2$d posts.'=>'Canza tsohuwar abun ciki: %1$d na posts %2$d.','Undo finished: %1$d restored, %2$d failed.'=>'An gama sauyawa: %1$d an dawo da su, %2$d sun gaza.','Conversion finished: %1$d converted, %2$d unchanged, %3$d failed.'=>'Canjin ya kammala: %1$d an canza, %2$d ba su canza ba, %3$d sun gaza.','Legacy content'=>'Tsohon abun ciki','Pages made with earlier versions of Page Builder Sandwich are converted to blocks in the background. Every post is backed up first, so each conversion can be undone.'=>'An canza shafukan da aka yi da tsofaffin sifofin Page Builder Sandwich zuwa blocks a bango. Ana yin madadin kowanne post a gaba, don haka ana iya mayar da kowanecanji zuwa yadda yake.','%d post still holds legacy content.'=>'Har yanzu post %d yana dauke da tsohon abun ciki.' . "\0" . 'Mawallafan %d har yanzu suna ɗauke da tsohon abun ciki.','%d post has a backup.'=>'Post %d yana da ajiyar baya.' . "\0" . '%d posts suna da madadin ajiyar bayanai.','%d post could not be handled'=>'Ba a iya sarrafa rubutu %d ba' . "\0" . 'Ba a iya sarrafa wallafe-wallafen %d ba','Post %d'=>'Rubutu na %d','Conversion started. It continues in the background; you can leave this page.'=>'An fara sauyawa. Yana ci gaba a bango; za ku iya barin wannan shafin.','Convert legacy content'=>'Maida tsohon abun ciki sabon salo','Restore every converted post to its legacy content? Changes made to those posts since they were converted will be lost.'=>'Sake dawo da kowane gidan yanar gizon da aka maida zuwa tsohuwar sigarsa? Canje-canjen da aka yi wa waɗannan gidajen yanar gizon tun lokacin da aka maida su za su ɓace.','Undo started. It continues in the background; you can leave this page.'=>'An fara sauyawa. Yana ci gaba a bango; zaku iya barin wannan shafin.','Undo all conversions'=>'Soke duk juyawar','Shortcode tag'=>'Lambar gajeren lokaci','Use letters, numbers, dashes and underscores only.'=>'Yi amfani da haruffa, lamba, da alamomin gajeren layi da na karkashin layi kawai.','Attribute name'=>'Sunan sifa','Add attribute'=>'Ƙara siffa','Content'=>'Abun ciki','Shortcode'=>'Gajeriyar lamba','Choose a shortcode tag in the block settings.'=>'Zaɓi alamar gajeren lamba (shortcode) a cikin saitunan bazuwar.','The "%s" control from the old editor is not available in the block editor. Enter the value as text.'=>'Ba a samun ikon "%s" daga tsohon edita a cikin editan tubali ba. Shigar da ƙimar a matsayin rubutu.','Choose image'=>'Zaɓi hoton','Choose file'=>'Zaɓi fayil','— Default —'=>'— Na asali —','Advanced styling'=>'Tsara salo na gaba','Inline CSS'=>'Inline CSS','CSS declarations, for example: min-height: 380px; background-color: #333'=>'Sanarwar CSS, alal misali: min-height: 380px; background-color: #333','Effects (legacy classes)'=>'Tasiri (tsofaffin aji)','Space-separated effect names carried over from older versions, for example: hover-shadow'=>'Sunayen tasiri masu rarrabuwa da sarari da aka kawo daga tsofaffin sigogi, alal misali: hover-shadow','Row'=>'Jergi','Width'=>'Fadi','Content width'=>'Fadin abubuwa','Full width'=>'Cikakken faɗi','Full width, content kept in the middle'=>'Cikakken faɗi, an ajiye abubuwa a tsakiya','Link'=>'Haɗi','Link address'=>'Adireshin mahada','Open in a new tab'=>'Buɗe a cikin sabon shafin yanar gizo','Link relationship'=>'Alakar mahada','Alignment'=>'Daidaita shafi','None'=>'Babu kowa','Left'=>'Hagu','Centre'=>'Tsakiya','Right'=>'Dama','Button text'=>'Rubutun maɓalli','Add text…'=>'Ƙara rubutu…','Icon'=>'Alama','SVG markup'=>'Alamar SVG','Scripts, links and external references are removed before the icon is shown.'=>'Ana cire rubututtuka, hanyoyin sadarwa, da kuma nassoshi na waje kafin a nuna hoton alamar.','Accessible label'=>'Alamar samuwa','Leave empty for a decorative icon.'=>'Bar a banza domin gunkin ado.','Paste SVG markup in the block settings.'=>'Manna da alamar SVG a cikin saitunan shafi.','New setting name'=>'Sabon sunan saitin','For example: title or text'=>'Misali: taken ko rubutu','Add setting'=>'Ƙara saitin','Widget'=>'Widget','Choose a widget'=>'Zaɓi widget','Widget area'=>'Yankin widget','Choose a widget area'=>'Zabi yankin widget','This image has no width and height, so the page will jump when it loads. Choose it from the Media Library, or set its width and height.'=>'Wannan hoton bazu da faɗi da tsayi ba, saboda haka shafin zai yi tsalle lokacin da ya loda. Zaɓi shi daga Laburare na Media, ko saita faɗinsa da tsayinsa.','This video is not from the Media Library, so its size is unknown and the page will jump when it loads. Upload it to the Media Library instead.'=>'Wannan bidiyon ba ya fitowa daga ɗakin karatu na Media, saboda haka girmansa ba a sani ba kuma shafin zai yi tsalle lokacin da ya โหลด. Maimakon haka, loda shi zuwa ɗakin karatu na Media.','An image, video or frame in this HTML has no width and height, so the page will jump when it loads. Add width and height attributes to it.'=>'Wani hoto ko bidiyo ko firam a cikin wannan HTML ba shi da faɗi da tsayi, don haka shafin zai yi tsalle lokacin da ya loda. Ƙara siffofin faɗi da tsayi a gare shi.','This embed resizes itself after it loads, which moves the content below it. Give it room or place it lower on the page.'=>'Wannan shigarwar tana sake girman kanta bayan ta loda, wanda ke motsa abubuwan da ke ƙasanta. Ba shi wuri ko sanya shi a ƙasa a shafin.','Layout shift'=>'Sauye-sauyen tsari','Heading'=>'Taken kai','Text'=>'Rubutu','Style'=>'Salo','Plain'=>'Na yau da kullum','Accent'=>'Harshe','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Babu harsunan da za a iya canzawa tsakaninsu. Maɓallin canza harshe yana bayyana ne lokacin da wani kari na fassara ya lissafa harsuna biyu ko fiye.','Switcher'=>'Mai canzawa','Show the current language'=>'Nuna harshen da ake ciki yanzu','%s is also editing this page. Saving may overwrite their changes.'=>'%s yana gyara wannan shafin kuma. Ajiye zai iya rubuta a kan gyare-gyarensa.','Block library'=>'Laburaren buloka','Layers'=>'Taruka','Close panel'=>'Rufe kwamitin','Page canvas'=>'Filin shafi','Revisions'=>'Gyare-gyare','Block settings'=>'Saitunan katange','Add block: %s'=>'Ƙara tubali: %s','(no title)'=>'(babu lakabi)','Open in Studio: %s'=>'Buɗe a Studio: %s','Undo'=>'Sake dawo da shi','Redo'=>'Sake yi','Show or hide layers'=>'Nuna ko ɓoye yadudduka','Show or hide the block library'=>'Nuna ko ɓoye ɗakin karatu na bulolin','Show revisions'=>'Nuna gyare-gyare','Open the normal editor'=>'Buɗe edita na al\'ada','Keyboard shortcuts'=>'Gajerun hanyoyin madannai','Preview: desktop'=>'Dubawa: kwamfutar tafi-da-gidanka','Preview: tablet'=>'Dubawa: kwamfutar hannu','Preview: mobile'=>'Gani a wayar hannu:','Copy style of the selected block'=>'Kwafi salin zababben tubalin','Paste style onto the selected block'=>'Liya sanyin salon a kan zababben tubalin','Copy the selected section'=>'Kwafi sashin da aka zaɓa','Paste a copied section'=>'Liƙa sashen da aka kwafi','Turn off safe mode'=>'Kashe yanayin aminci','Turn on safe mode (other plugins off, for you, in Studio only)'=>'Kunna yanayin aminci (sauran ɗorawa a kashe, a gare ka, a Studio kaɗai)','Published'=>'An buga','Scheduled'=>'An tsara','Pending review'=>'Ana jiran dubawa','Private'=>'Maigirma','Draft'=>'Da-aka-tsara','All changes saved'=>'An adana duk sauye-sauye','Saving…'=>'Ana adanawa...','Autosaving…'=>'Ana adanawa ta atomatik…','Unsaved changes'=>'Canjin da ba a ajiyewa ba','autosaved'=>'an adana ta atomatik','Desktop preview'=>'Samfurin kwamfuta ta tebur','Tablet preview'=>'Dubawar kwamfutar tafi-da-gidanka','Mobile preview'=>'Duban wayar hannu','Studio toolbar'=>'Sandar kayan aiki ta Studio','Back to the normal editor'=>'Koma zuwa edita na al\'ada','Page title'=>'Sunan shafi','Preview width'=>'Fadin samfoti','Command palette'=>'Kundin umarni','View page (opens in a new tab)'=>'Duba shafi (yana buɗe a cikin sabon shafi)','Update'=>'Sabunta','Save draft'=>'Ajiye daftari','Publish'=>'Bugawa','Restore unsaved changes?'=>'Sake dawo da canjin da ba a ajiyee ba?','This page has changes that were never saved. They were kept in this browser:'=>'Wannan shafin yana da canje-canjen da ba a taba adana su ba. An kiyaye su a cikin wannan burauz din:','This page has a newer autosave than the saved version:'=>'Wannan shafin yana da sabon kwafin da aka adana ta atomatik fiye da sigar da aka adana:','Restore unsaved changes'=>'Mayar da canje-canjen da ba a ajiyewa ba','Discard'=>'Kora da shi','Revisions could not be loaded.'=>'Ba a iya loda gyare-gyaren ba.','Revision restored. Save to keep it, or undo to go back.'=>'An dawo da fasalin da aka gyara. Ajiye don riƙe shi, ko a soke don komawa baya.','Close revisions'=>'Rufe bita','No revisions yet. Each save makes one.'=>'Ba a yi gyare-gyare ba tukuna. Kowace adanawa tana ƙirƙirar ɗaya.','Revision from %s'=>'Revision daga %s','Restore this revision'=>'Maido da wannan bita','Cancel'=>'Soke','Safe mode could not be changed.'=>'Ba aweza canza yanayin aminci ba.','Safe mode is on.'=>'Yanayin tsaro yana kunne.','%d other plugin is switched off, for you and in Sandwich Studio only. The live site and other users are not affected.'=>'An kashe wani plug-in %d daban, domin ku kadai kuma a cikin Sandwich Studio kadai. Wannan ba zai shafi raddadin rukunin yanar gizo na gaske da sauran masu amfani ba.' . "\0" . 'Wasu plugins %d an kashe su, domin ku da kuma a Sandwich Studio kadai. Ba a shafar shafin da ke aiki da sauran masu amfani ba.','Safe mode: switch other plugins off in Studio, for you only'=>'Yanayin lafiya: kashe sauranfulojoji a cikin Studio, don ku kadai','Safe mode'=>'Yanayin tsaro','Save your changes.'=>'Ajiye canje-canjenku.','Undo your last change.'=>'Sake dawo da sauye-kayenku na ƙarshe.','Redo your last undo.'=>'Maimaita abin da ka soke na karshe.','Show or hide the layers panel.'=>'Nuna ko ɓoye kwamitin yadudduka.','Display these keyboard shortcuts.'=>'Nuna waɗannan gajerun hanyoyin madannai.','Select a block first.'=>'Zaɓi buloka tukuna.','Style copied. Paste it onto any block, on this site or another.'=>'An kwafi salon. Manna shi a kan kowane buloku, a kan wannan shafin ko wani.','The browser refused to copy.'=>'Mai binciken ya ki kwafi.','Section copied. Paste it into any page, on this site or another.'=>'An kwafi sashen. Manna shi a kowane shafi, a wannan shafin ko wani.','The clipboard does not hold a style copied from Sandwich Studio.'=>'Ba a adana salon da aka kwafi daga Sandwich Studio a cikin allo ba.','Style pasted onto %d block.'=>'Salon da aka manna a kan tubali %d.' . "\0" . 'An shafa salo a kan tubalan %d.','That style does not fit the selected block.'=>'Wannan salon bai dace da katangar da aka zaɓa ba.','The clipboard does not hold a copied section.'=>'Allon kwafi ba shi da wani yanki da aka kwafa.','Section pasted.'=>'An manna da aka liƙa.','Paste style'=>'Manna salon salo','Paste section'=>'Manna sashe','Press Ctrl+V (or Cmd+V on a Mac) here to paste'=>'Latsa Ctrl+V (ko Cmd+V a kan Mac) anan don mannawa','Copy style'=>'Kofe salo','Copy section'=>'Kwafi sashin','Edit in Sandwich Studio'=>'Gyara a cikin Sandwich Studio','Saving failed. Check your connection and try again; your changes are kept in this browser.'=>'An adana ba ta yi nasara ba. Duba hanyar sadarwarku kuma ku sake gwadawa; an kiyaye sauye-sauyenkanku a cikin wannan burauz din.','Published.'=>'An buga','Saved.'=>'An adana.','block titleButton link'=>'Mahadar maɓalli','block descriptionA link styled as a button.'=>'Hanyar haɗi mai salo kamar maɓalli.','block keywordbutton'=>'mabuɗi','block keywordlink'=>'mahada','block keywordcall to action'=>'kira zuwa ga aiki','block titleColumn'=>'Shafi\'i','block descriptionA column inside a row. It can hold any block.'=>'Wani shafi a cikin jere. Yana iya ɗaukar kowane buloka.','block keywordcolumn'=>'shafi','block keywordlayout'=>'tsari','block titleLanguage switcher (sample)'=>'Mai sauya harshe (misali)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Ana lissafa harsunan shafin daga matosai na fassara, idan akwai mai aiki. Ba ya nuna komai in ba haka ba.','block keywordlanguage'=>'Harshe','block keywordswitcher'=>'mai sauyawa','block titleSample content'=>'Samfurin abun ciki','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Wani take da sakin layi, waɗanda aka nuna da sunayen aji marasa ɓata guda. Shi ne tubalin misali don kwangilar fassara.','block keywordsample'=>'misali','block keywordtext'=>'rubutu','block titleIcon'=>'Alama','block descriptionAn SVG icon. The markup is cleaned before it is shown.'=>'Alamar SVG. An tsabtace lambar kafin a nuna ta.','block keywordicon'=>'gunkadi','block keywordsvg'=>'svg','block titleRow'=>'Jergi','block descriptionA row of columns. Stays readable if the plugin is ever turned off.'=>'Jerin shafuka. Zai ci gaba da karatu idan an kashe fasalin.','block keywordrow'=>'layla','block keywordcolumns'=>'shafiuka','block titleShortcode (add-on)'=>'Shortcode (add-on)','block descriptionA shortcode from an add-on written for the classic Page Builder Sandwich editor, with the settings the add-on declared.'=>'Gajeren lambar daga wani kari da aka rubuta don tsohon editan Page Builder Sandwich, tare da saitunan da karin ya bayyana.','block keywordshortcode'=>'gajerun lambobi','block keywordadd-on'=>'ƙari','block titleWidget area'=>'Yankin Widget','block descriptionShows the widgets in one of the theme\'s widget areas.'=>'Yana nuna widgets a cikin ɗayan wuraren widget na jigon.','block keywordsidebar'=>'ashar gefe','block keywordwidget area'=>'yankin widget','block titleWidget'=>'Widget','block descriptionShows one of the site\'s registered classic widgets.'=>'Yana nuna ɗaya daga cikin tsofaffin widgets ɗin da aka yi wa rajista na shafin.','block keywordwidget'=>'widget']];